// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 first, uint256 second, address actor) public {
        vm.assume(first <= VALUE_CAP);
        vm.assume(second <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.deal(actor, first + second);

        vm.prank(actor);
        c.Put{value: first}(0);
        vm.prank(actor);
        c.Put{value: second}(0);

        (uint unlockTime, uint balance) = c.Acc(actor);
        assertTrue(balance == first + second && unlockTime > 0);
    }
}
